// Devuelve al orquestador { recomendaciones } en JSON limpio.
const resultado = $input.first().json;
if (resultado.error) return [{ json: { recomendaciones: [], error: 'El agente recomendador no está disponible.' } }];
try {
  const texto = String(resultado.output ?? '').replace(/```(?:json)?/gi, '');
  const json = JSON.parse(texto.slice(texto.indexOf('{'), texto.lastIndexOf('}') + 1));
  const recomendaciones = (Array.isArray(json.recomendaciones) ? json.recomendaciones : []).slice(0, 4);
  return [{ json: { recomendaciones } }];
} catch (error) {
  return [{ json: { recomendaciones: [], error: 'El recomendador devolvió un formato inválido.' } }];
}
